+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.List;
+import java.util.Locale;
+import java.util.Objects;
+import java.util.Set;
+
+/**
+ * The predicates applied by the customer search.  This is deliberately a
+ * backend value object: a grid page and its count query receive the same
+ * filter, rather than the UI filtering rows it has already loaded.
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    public CustomerFilter {
+        name = Objects.requireNonNullElse(name, "");
+        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
+    }
+
+    public static CustomerFilter empty() {
+        return new CustomerFilter("", Set.of());
+    }
+
+    /** Whether this customer satisfies both the name and status predicates. */
+    public boolean matches(Customer customer) {
+        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+            return false;
+        }
+
+        String firstName = fold(customer.firstName());
+        String lastName = fold(customer.lastName());
+        return terms().stream().allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
+
+    private List<String> terms() {
+        String trimmed = name.trim();
+        if (trimmed.isEmpty()) {
+            return List.of();
+        }
+        return List.of(trimmed.split("\\s+")).stream().map(CustomerFilter::fold).toList();
+    }
+
+    private static String fold(String text) {
+        return Normalizer.normalize(text, Normalizer.Form.NFD)
+                .replaceAll("\\p{M}+", "")
+                .toLowerCase(Locale.ROOT);
+    }
+}
